import copy
import unittest

from solution import reposition


class RepositionTests(unittest.TestCase):
    def test_cross_column_move_and_no_aliasing(self):
        layout = {"todo": ["a", "b"], "done": ["c"]}
        snapshot = copy.deepcopy(layout)
        result = reposition(layout, "b", "done", 1)
        self.assertEqual(result, {"todo": ["a"], "done": ["c", "b"]})
        self.assertEqual(layout, snapshot)
        self.assertEqual(list(result), list(layout))
        for column in layout:
            self.assertIsNot(result[column], layout[column])

    def test_same_column_index_is_interpreted_after_removal(self):
        layout = {"column": ["a", "b", "c", "d"]}
        self.assertEqual(
            reposition(layout, "a", "column", 2),
            {"column": ["b", "c", "a", "d"]},
        )
        self.assertEqual(
            reposition(layout, "c", "column", 0),
            {"column": ["c", "a", "b", "d"]},
        )
        self.assertEqual(
            reposition(layout, "a", "column", 3),
            {"column": ["b", "c", "d", "a"]},
        )
        self.assertEqual(layout, {"column": ["a", "b", "c", "d"]})

    def test_boundary_indices_into_empty_and_nonempty_columns(self):
        layout = {"source": ["card"], "target": []}
        self.assertEqual(
            reposition(layout, "card", "target", 0),
            {"source": [], "target": ["card"]},
        )
        layout = {"source": ["card"], "target": ["x", "y"]}
        self.assertEqual(
            reposition(layout, "card", "target", 2),
            {"source": [], "target": ["x", "y", "card"]},
        )

    def test_invalid_indices_raise_without_mutation(self):
        layout = {"left": ["a", "b"], "right": ["c"]}
        snapshot = copy.deepcopy(layout)
        for index in (-1, 2):
            with self.subTest(index=index), self.assertRaises(IndexError):
                reposition(layout, "a", "right", index)
            self.assertEqual(layout, snapshot)
        for index in (True, False, 1.0, "1", None):
            with self.subTest(index=index), self.assertRaises(TypeError):
                reposition(layout, "a", "right", index)
            self.assertEqual(layout, snapshot)

    def test_unknown_names_and_argument_types(self):
        layout = {"left": ["a"], "right": []}
        with self.assertRaises(KeyError):
            reposition(layout, "missing", "right", 0)
        with self.assertRaises(KeyError):
            reposition(layout, "a", "missing", 0)
        with self.assertRaises(TypeError):
            reposition(layout, 1, "right", 0)
        with self.assertRaises(TypeError):
            reposition(layout, "a", 1, 0)

    def test_malformed_layouts(self):
        with self.assertRaises(TypeError):
            reposition([], "a", "x", 0)
        with self.assertRaises(ValueError):
            reposition({"": ["a"]}, "a", "", 0)
        with self.assertRaises(TypeError):
            reposition({"x": ("a",)}, "a", "x", 0)
        for layout in ({"x": [""]}, {"x": [1]}):
            with self.subTest(layout=layout), self.assertRaises(ValueError):
                reposition(layout, "a", "x", 0)
        with self.assertRaises(ValueError):
            reposition({"x": ["a"], "y": ["a"]}, "a", "x", 0)


if __name__ == "__main__":
    unittest.main()

